import { View, Text, FlatList, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

const PRODUCTS = [
  { id: "p1", name: "Чихэвч", price: 159000 },
  { id: "p2", name: "Гар цаг", price: 249000 },
  { id: "p3", name: "Нарны шил", price: 89000 },
  { id: "p4", name: "Цүнх", price: 129000 },
];
const fakeApi = () => new Promise((res) => setTimeout(() => res(PRODUCTS), 200));

function App() {
  const [items, setItems] = useState([]);
  // энд бичнэ үү: useEffect дотор fakeApi()-г татаж items-д хадгал
  return (
    <FlatList
      nativeID="list"
      data={items}
      keyExtractor={(x) => x.id}
      renderItem={({ item }) => <Text testID="row" style={styles.row}>{item.name}</Text>}
      style={styles.list}
    />
  );
}

const styles = StyleSheet.create({
  list: { flex: 1, padding: 16 },
  row: { fontSize: 16, paddingVertical: 12, borderBottomWidth: 1, borderColor: "#e2e8f0" },
});

registerRootComponent(App);

import { View, Text, FlatList, StyleSheet } from "react-native";
import { useState, useEffect } from "react";
import { registerRootComponent } from "expo";

const PRODUCTS = [
  { id: "p1", name: "Чихэвч", price: 159000 },
  { id: "p2", name: "Гар цаг", price: 249000 },
  { id: "p3", name: "Нарны шил", price: 89000 },
  { id: "p4", name: "Цүнх", price: 129000 },
];
const fakeApi = () => new Promise((res) => setTimeout(() => res(PRODUCTS), 200));

function App() {
  const [items, setItems] = useState([]);
  useEffect(() => {
    let alive = true;
    fakeApi().then((data) => { if (alive) setItems(data); });
    return () => { alive = false; };
  }, []);
  return (
    <FlatList
      nativeID="list"
      data={items}
      keyExtractor={(x) => x.id}
      renderItem={({ item }) => <Text testID="row" style={styles.row}>{item.name}</Text>}
      style={styles.list}
    />
  );
}

const styles = StyleSheet.create({
  list: { flex: 1, padding: 16 },
  row: { fontSize: 16, paddingVertical: 12, borderBottomWidth: 1, borderColor: "#e2e8f0" },
});

registerRootComponent(App);
